  id: string;
  latest_charge?: string | { id: string } | null;
  metadata?: Record<string, string | undefined> | null;
  amount?: number;                                     // S17
  currency?: string | null;                            // S17
  amount_details?: {                                   // S17
    tax?: { amount: number } | null;
    tax_breakdown?: Array<{
