### Edit 2 — Add S17 tax mirror block in `payment_intent.succeeded` handler

Find `handlePaymentIntentStatusChange` function. Inside the `if (eventType === 'payment_intent.succeeded')` block, AFTER the existing block that calls `RPC.COMMISSION_SPLIT_RECORD` (the commission-split-record block — Track D from S16). Insert this new block BEFORE the closing `}` of the `if (eventType === 'payment_intent.succeeded')` branch:

```ts
// === S17 — Tax mirror + per-tax-line attribution ===

const taxTotal = pi.amount_details?.tax?.amount ?? 0;
const taxBreakdown = pi.amount_details?.tax_breakdown ?? [];

// 1. Update stripe_charges.tax_amount_cents via charge update RPC.
// Track D extended stripe_charge_update_status_from_webhook to accept p_tax_amount_cents.
const { error: chargeTaxErr } = await supabase.rpc(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK, {
  p_payment_intent_id: pi.id,
  p_status: 'succeeded',
  p_charge_id: typeof pi.latest_charge === 'string'
    ? pi.latest_charge
    : (pi.latest_charge?.id ?? null),
  p_transfer_id: null,
  p_application_fee_id: null,
  p_tax_amount_cents: taxTotal,
});
if (chargeTaxErr) {
  logger.error({ pi_id: pi.id, err: chargeTaxErr },
    'S17: stripe_charge_update_status_from_webhook (tax pass) failed');
  throw chargeTaxErr;
}

// 2. Per-tax-line attribution to commission_splits.
if (taxBreakdown.length > 0 && studioId && bookingId) {
  // §S13.3 — types.ts regen pending
  const fromUntyped = supabase.from.bind(supabase) as unknown as (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col2: string, val2: string) => {
          order: (col: string, opts: { ascending: boolean }) => {
            limit: (n: number) => {
              maybeSingle: () => Promise<{ data: { id: string } | null; error: unknown }>;
            };
          };
        };
      };
    };
  };
  const { data: parentSplitData } = await fromUntyped('commission_splits')
    .select('id')
    .eq('booking_id', bookingId)
    .eq('kind', 'split')
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle();

  if (parentSplitData) {
    const parentSplitId = parentSplitData.id;
    const eventDate = new Date();
    const quarter = Math.floor(eventDate.getMonth() / 3) + 1;
    const period = `${eventDate.getFullYear()}-Q${quarter}`;

    // Look up studio's primary location once.
    const fromUntypedSelect = supabase.from.bind(supabase) as unknown as (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          limit: (n: number) => {
            maybeSingle: () => Promise<{ data: { id: string } | null; error: unknown }>;
          };
        };
      };
    };
    const { data: locationData } = await fromUntypedSelect('locations')
      .select('id')
      .eq('studio_id', studioId)
      .limit(1)
      .maybeSingle();

    for (const line of taxBreakdown) {
      const country = line.jurisdiction?.country ?? null;
      const state = line.jurisdiction?.state ?? null;
      const jurisdiction = state ? `${country ?? 'US'}-${state}` : (country ?? 'UNKNOWN');
      const taxLineId = `${parentSplitId}:${jurisdiction}`;

      const { error: lineErr } = await supabase.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_RECORD, {
        p_parent_split_id: parentSplitId,
        p_tax_line_id: taxLineId,
        p_jurisdiction: jurisdiction,
        p_tax_amount_cents: line.amount,
      });
      if (lineErr) {
        logger.error({ pi_id: pi.id, parent_split: parentSplitId, jurisdiction, err: lineErr },
          'S17: commission_split_tax_line_record failed — recoverable via reconciliation');
      }

      if (locationData) {
        const { error: accrueErr } = await supabase.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
          p_studio_id: studioId,
          p_location_id: locationData.id,
          p_jurisdiction: jurisdiction,
          p_period: period,
          p_amount_collected_cents: line.amount,
        });
        if (accrueErr) {
          logger.error({ pi_id: pi.id, jurisdiction, period, err: accrueErr },
            'S17: tax_remittance_accrue failed — recoverable via reconciliation');
        }
      }
    }
  } else {
    logger.warn({ pi_id: pi.id, booking_id: bookingId },
      'S17: parent commission_split not found — tax breakdown not recorded');
  }
} else if (taxTotal > 0 && studioId) {
  // Single-line fallback — no breakdown but tax was charged.
  const fallbackJurisdiction = 'UNKNOWN';
  const eventDate = new Date();
  const quarter = Math.floor(eventDate.getMonth() / 3) + 1;
  const period = `${eventDate.getFullYear()}-Q${quarter}`;

  const fromUntypedSelect = supabase.from.bind(supabase) as unknown as (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        limit: (n: number) => {
          maybeSingle: () => Promise<{ data: { id: string } | null; error: unknown }>;
        };
      };
    };
  };
  const { data: locationData } = await fromUntypedSelect('locations')
    .select('id')
    .eq('studio_id', studioId)
    .limit(1)
    .maybeSingle();

  if (locationData) {
    await supabase.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
      p_studio_id: studioId,
      p_location_id: locationData.id,
      p_jurisdiction: fallbackJurisdiction,
      p_period: period,
      p_amount_collected_cents: taxTotal,
    });
  }
} else if (taxTotal === 0) {
  logger.info({ pi_id: pi.id },
    'S17: tax not in PI payload — webhook tax mirror skipped, may need cron sync');
}
```

If `studioId` and `bookingId` are not in scope at the insertion point, hoist their declarations earlier in the function (they're declared from `pi.metadata` for the existing commission-split block — verify the existing scope).

